13	const TS_EXTENSIONS = ['.ts', '.tsx', '.cts', '.mts'] as const;
14	const PACKAGE = '@nx/jest';
15	const OLD_NAME = 'jestProjectGenerator';
16	const NEW_NAME = 'configurationGenerator';
