20	export default async function rewriteJestProjectGenerator(
21	  tree: Tree
22	): Promise<void> {
23	  let touchedCount = 0;
24	
25	  visitNotIgnoredFiles(tree, '.', (filePath) => {
26	    if (!TS_EXTENSIONS.some((ext) => filePath.endsWith(ext))) {
27	      return;
28	    }
29	    const original = tree.read(filePath, 'utf-8');
30	    if (
31	      !original ||
32	      !original.includes(OLD_NAME) ||
33	      !original.includes(PACKAGE)
34	    ) {
35	      return;
36	    }
37	    const updated = rewriteJestProjectGeneratorUsage(original);
38	    if (updated !== original) {
39	      tree.write(filePath, updated);
40	      touchedCount += 1;
41	    }
42	  });
43	
44	  if (touchedCount > 0) {
45	    logger.info(
46	      `Replaced the deprecated \`${OLD_NAME}\` with \`${NEW_NAME}\` in ${touchedCount} file(s).`
47	    );
48	  }
49	
50	  await formatFiles(tree);
51	}
