53	export function rewriteJestProjectGeneratorUsage(source: string): string {
54	  ts ??= ensurePackage<typeof import('typescript')>('typescript', '*');
55	  const sourceFile = ts.createSourceFile(
56	    'tmp.ts',
57	    source,
58	    ts.ScriptTarget.Latest,
59	    /* setParentNodes */ true,
60	    ts.ScriptKind.TSX
61	  );
62	
63	  // `jestProjectGenerator as alias` — only the imported name changes.
64	  let aliasedSpecifier: ImportSpecifier | undefined;
65	  // `jestProjectGenerator` — the local binding is the old name itself.
66	  let plainSpecifier: ImportSpecifier | undefined;
67	  // Whether `configurationGenerator` is already a binding in the file, which
68	  // means a plain rename would produce a duplicate import specifier.
69	  let newNameAlreadyBound = false;
70	
71	  for (const stmt of sourceFile.statements) {
72	    if (!ts.isImportDeclaration(stmt)) continue;
73	    if (
74	      !ts.isStringLiteral(stmt.moduleSpecifier) ||
75	      stmt.moduleSpecifier.text !== PACKAGE
76	    ) {
77	      continue;
78	    }
79	    const named = stmt.importClause?.namedBindings;
80	    if (!named || !ts.isNamedImports(named)) continue;
81	    for (const spec of named.elements) {
82	      const importedName = (spec.propertyName ?? spec.name).text;
83	      if (importedName === OLD_NAME) {
84	        if (spec.propertyName) {
85	          aliasedSpecifier = spec;
86	        } else {
87	          plainSpecifier = spec;
88	        }
89	      }
90	      if (importedName === NEW_NAME || spec.name.text === NEW_NAME) {
91	        newNameAlreadyBound = true;
92	      }
93	    }
94	  }
95	
96	  if (!aliasedSpecifier && !plainSpecifier) {
97	    return source;
98	  }
99	
100	  const changes: StringChange[] = [];
101	
102	  // `jestProjectGenerator as alias` -> `configurationGenerator as alias`.
103	  // Call sites use `alias`, so only the imported name is rewritten.
104	  if (aliasedSpecifier?.propertyName) {
105	    replaceNode(sourceFile, aliasedSpecifier.propertyName, NEW_NAME, changes);
106	  }
107	
108	  if (plainSpecifier) {
109	    if (newNameAlreadyBound) {
110	      // A plain rename would collide with the existing `configurationGenerator`
111	      // binding, so alias the import and leave the call sites untouched.
112	      replaceNode(
113	        sourceFile,
114	        plainSpecifier.name,
115	        `${NEW_NAME} as ${OLD_NAME}`,
116	        changes
117	      );
118	    } else {
119	      // Rename the import binding and every bare-identifier usage in the file.
120	      for (const id of collectBareIdentifiers(sourceFile)) {
121	        replaceNode(sourceFile, id, NEW_NAME, changes);
122	      }
123	    }
124	  }
125	
126	  return changes.length > 0 ? applyChangesToString(source, changes) : source;
127	}
