129	/**
130	 * Collect every `jestProjectGenerator` identifier that is a standalone
131	 * reference — the import binding and its call sites — while skipping member
132	 * accesses like `someObject.jestProjectGenerator`, which are unrelated.
133	 */
134	function collectBareIdentifiers(sourceFile: SourceFile): Identifier[] {
135	  const found: Identifier[] = [];
136	  const visit = (node: Node): void => {
137	    if (ts!.isIdentifier(node) && node.text === OLD_NAME) {
138	      const parent = node.parent;
139	      const isMemberName =
140	        parent &&
141	        ts!.isPropertyAccessExpression(parent) &&
142	        parent.name === node;
143	      const isQualifiedName =
144	        parent && ts!.isQualifiedName(parent) && parent.right === node;
145	      if (!isMemberName && !isQualifiedName) {
146	        found.push(node);
147	      }
148	    }
149	    ts!.forEachChild(node, visit);
150	  };
151	  visit(sourceFile);
152	  return found;
153	}
154	
155	function replaceNode(
156	  sourceFile: SourceFile,
157	  node: Node,
158	  text: string,
159	  changes: StringChange[]
160	): void {
161	  const start = node.getStart(sourceFile);
162	  const end = node.getEnd();
163	  changes.push(
164	    { type: ChangeType.Delete, start, length: end - start },
165	    { type: ChangeType.Insert, index: start, text }
166	  );
167	}
