17	function findPropertyAssignment(
18	  object: ts.ObjectLiteralExpression,
19	  propertyName: string
20	) {
21	  if (!tsModule) {
22	    tsModule = ensureTypescript();
23	  }
24	
25	  return object.properties.find((prop) => {
26	    if (!tsModule.isPropertyAssignment(prop)) {
27	      return false;
28	    }
29	    const propNameText = prop.name.getText();
30	    if (propNameText.match(/^["'].+["']$/g)) {
31	      return JSON.parse(propNameText.replace(/'/g, '"')) === propertyName;
32	    }
