const FLAT_GENERATOR = '@nx/jest:configuration';
const PACKAGE = '@nx/jest';
const NESTED_GENERATOR = 'configuration';

/**
 * Rewrites the deprecated `skipSetupFile` generator default for the
 * `@nx/jest:configuration` generator to its modern equivalent:
 * - `skipSetupFile: true`  -> `setupFile: 'none'` (unless a `setupFile` is
 *   already configured, in which case the existing value is preserved).
 * - `skipSetupFile: false` -> the option is simply dropped.
 *
 * Handles both the flat (`generators['@nx/jest:configuration']`) and nested
 * (`generators['@nx/jest']['configuration']`) generator default forms, in both
 * `nx.json` and per-project configuration files.
 */
export default async function migrateJestConfigurationSkipSetupFile(
  tree: Tree
): Promise<void> {
  const nxJson = readNxJson(tree);
  if (nxJson?.generators && migrateGenerators(nxJson.generators)) {
    updateNxJson(tree, nxJson);
  }

  const projects = getProjects(tree);
  for (const [projectName, project] of projects) {
    if (project.generators && migrateGenerators(project.generators)) {
      updateProjectConfiguration(tree, projectName, project);
    }
  }

  await formatFiles(tree);
}

/**
 * Migrate any `@nx/jest:configuration` generator defaults contained in a
 * `generators` map (flat and/or nested form). Returns `true` when a change was
 * made so callers know whether the surrounding config needs to be written back.
 */
function migrateGenerators(generators: Record<string, any>): boolean {
  let changed = false;

  // Flat form: generators['@nx/jest:configuration'] = { ... }
  if (isPlainObject(generators[FLAT_GENERATOR])) {
    if (migrateDefaults(generators, FLAT_GENERATOR)) {
      changed = true;
    }
  }

  // Nested form: generators['@nx/jest'] = { configuration: { ... } }
  const nested = generators[PACKAGE];
  if (isPlainObject(nested) && isPlainObject(nested[NESTED_GENERATOR])) {
    if (migrateDefaults(nested, NESTED_GENERATOR)) {
      changed = true;
    }
  }

  return changed;
