function migrateDefaults(container: Record<string, any>, key: string): boolean {
  const defaults = container[key];
  if (!('skipSetupFile' in defaults)) {
    return false;
  }

  const skipSetupFile = defaults.skipSetupFile;
  delete defaults.skipSetupFile;

  // `skipSetupFile: true` disabled the setup file, which is now expressed as
  // `setupFile: 'none'`. Never clobber an explicitly configured `setupFile`.
  if (skipSetupFile === true && !('setupFile' in defaults)) {
    defaults.setupFile = 'none';
  }

  // Once the only option was removed, drop the now-empty generator entry.
  if (Object.keys(defaults).length === 0) {
    delete container[key];
  }

  return true;
