      if (writes.has(normalizedConfig)) {
        if (writes.get(normalizedConfig) !== setupFile) {
          // Two scopes want to write different setup files into the same Jest
          // config. Keep the first and surface the ambiguity.
          needsFollowUp = true;
        }
        return;
      }
      writes.set(normalizedConfig, setupFile);
    };

    for (const target of Object.values(project.targets ?? {})) {
      if (!JEST_EXECUTORS.has(target.executor)) {
        continue;
