      const baseOptions = (target.options ?? {}) as Record<string, any>;
      const baseSetupFile =
        baseOptions.setupFile ?? resolveToken(defaultSetupFile, projectRoot);
      const baseJestConfig =
        baseOptions.jestConfig ?? resolveToken(defaultJestConfig, projectRoot);
