type JestTargetDefaults = {
  setupFile?: string;
  jestConfig?: string;
};

function readJestTargetDefaults(nxJson: any): JestTargetDefaults {
  const targetDefaults = nxJson?.targetDefaults;
  if (!targetDefaults) {
    return {};
  }

  const options = getJestTargetDefaultEntry(targetDefaults)?.options;
  return {
    setupFile: options?.setupFile,
    jestConfig: options?.jestConfig,
  };
}

function getJestTargetDefaultEntry(
  targetDefaults: any
): TargetConfiguration | undefined {
  if (Array.isArray(targetDefaults)) {
    return targetDefaults.find(
      (entry) =>
        JEST_EXECUTORS.has(entry.target) || JEST_EXECUTORS.has(entry.executor)
    );
  }

  for (const [targetOrExecutor, targetConfig] of Object.entries<any>(
    targetDefaults
  )) {
    if (
      JEST_EXECUTORS.has(targetOrExecutor) ||
      JEST_EXECUTORS.has(targetConfig.executor)
    ) {
      return targetConfig;
    }
  }

  return undefined;
}

function removeSetupFileFromTargetDefaults(tree: Tree): void {
  const nxJson = readNxJson(tree);
  const entry = getJestTargetDefaultEntry(nxJson?.targetDefaults);
  if (entry?.options && 'setupFile' in entry.options) {
    delete entry.options.setupFile;
    updateNxJson(tree, nxJson);
  }
}

/**
 * Resolve token placeholders (e.g. `{projectRoot}`) found in target-default
 * option values into a concrete workspace-relative path.
 */
function resolveToken(
  value: string | undefined,
  projectRoot: string
): string | undefined {
  if (!value) {
    return value;
  }
  const replaced = value
    .replace(/\{projectRoot\}/g, projectRoot)
    .replace(/\{workspaceRoot\}/g, '');
  return posix.normalize(replaced);
}

